export const videosById = new Map<string, VideoExample>(allVideos.map(v => [v.dbId!, v]));
export function getVideoByDbId(id: string): VideoExample | undefined { return videosById.get(id); }

// Resolve a short IG/TikTok videoId → compound dbId (for admin paste-URL flow)
export function resolveShortId(shortId: string): VideoExample | undefined {
  return allVideos.find(v => v.id === shortId);
}
